import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.DqVSm8kp.js";const m=JSON.parse('{"title":"Paramètres","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/settings.md","filePath":"fr/guide/settings.md"}'),s={name:"fr/guide/settings.md"};function l(n,e,i,u,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="parametres" tabindex="-1">Paramètres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Paramètres&quot;">​</a></h1><p>La page Paramètres vous permet de configurer votre connexion Ollama, les paramètres par défaut des modèles et les préférences de l&#39;application.</p><p><strong>Élément de la barre latérale :</strong> Paramètres <strong>Route :</strong> <code>/settings</code></p><h2 id="connexion" tabindex="-1">Connexion <a class="header-anchor" href="#connexion" aria-label="Permalink to &quot;Connexion&quot;">​</a></h2><h3 id="url-ollama" tabindex="-1">URL Ollama <a class="header-anchor" href="#url-ollama" aria-label="Permalink to &quot;URL Ollama&quot;">​</a></h3><p>Définissez l&#39;URL où Ollama est en cours d&#39;exécution. Par défaut : <code>http://localhost:11434</code>.</p><h3 id="test-de-connexion" tabindex="-1">Test de connexion <a class="header-anchor" href="#test-de-connexion" aria-label="Permalink to &quot;Test de connexion&quot;">​</a></h3><p>Cliquez sur <strong>Tester la connexion</strong> pour vérifier que LLMxRay peut atteindre Ollama. Le résultat affiche :</p><ul><li><strong>Connecté</strong> (vert) -- Ollama est accessible et répond</li><li><strong>Déconnecté</strong> (rouge) -- Vérifiez que <code>ollama serve</code> est en cours d&#39;exécution</li></ul><div class="tip custom-block"><p class="custom-block-title">Ollama distant</p><p>Si Ollama tourne sur une autre machine, saisissez son adresse IP et son port (par ex., <code>http://192.168.1.100:11434</code>). Assurez-vous que le proxy Vite est mis à jour dans <code>vite.config.ts</code> ou que le CORS est configuré sur l&#39;instance Ollama distante.</p></div><h2 id="parametres-par-defaut" tabindex="-1">Paramètres par défaut <a class="header-anchor" href="#parametres-par-defaut" aria-label="Permalink to &quot;Paramètres par défaut&quot;">​</a></h2><h3 id="temperature" tabindex="-1">Température <a class="header-anchor" href="#temperature" aria-label="Permalink to &quot;Température&quot;">​</a></h3><p>Contrôle l&#39;aléatoire dans les sorties du modèle. Affichée avec une <strong>échelle visuelle</strong> et une <strong>infobulle pédagogique</strong> :</p><table tabindex="0"><thead><tr><th>Valeur</th><th>Effet</th></tr></thead><tbody><tr><td><strong>0</strong></td><td>Déterministe -- choisit toujours le token le plus probable</td></tr><tr><td><strong>0.7</strong></td><td>Équilibré -- valeur par défaut pour la plupart des cas d&#39;utilisation</td></tr><tr><td><strong>1.0+</strong></td><td>Créatif -- sortie plus variée, parfois surprenante</td></tr></tbody></table><h3 id="longueur-de-contexte" tabindex="-1">Longueur de contexte <a class="header-anchor" href="#longueur-de-contexte" aria-label="Permalink to &quot;Longueur de contexte&quot;">​</a></h3><p>Définit le nombre maximal de tokens que le modèle prend en compte. Des valeurs plus élevées permettent des conversations plus longues mais consomment plus de mémoire.</p><p>Les deux paramètres incluent des échelles visuelles et des explications en langage courant de ce que fait chaque réglage.</p><h2 id="catalogue-de-modeles" tabindex="-1">Catalogue de modèles <a class="header-anchor" href="#catalogue-de-modeles" aria-label="Permalink to &quot;Catalogue de modèles&quot;">​</a></h2><p>L&#39;onglet Modèles (également accessible comme élément de la barre latérale) fournit :</p><ul><li>Un catalogue consultable des modèles installés</li><li>Des badges de détection des capacités (raisonnement, vision, embedding, appel d&#39;outils)</li><li>Détails d&#39;architecture et nombre de paramètres</li><li>Fonctionnalités de comparaison pour évaluer les modèles côté à côté</li></ul><p>Consultez le chapitre <a href="./models.html">Modèles</a> pour tous les détails.</p><h2 id="theme" tabindex="-1">Thème <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Thème&quot;">​</a></h2><p>Basculez entre :</p><ul><li><strong>Mode sombre</strong> -- Par défaut, optimisé pour une utilisation prolongée</li><li><strong>Mode clair</strong> -- Alternative à haut contraste</li><li><strong>Système</strong> -- Suit la préférence de votre OS</li></ul><p>Le bouton de thème est également disponible dans la barre d&#39;en-tête.</p><h2 id="google-oauth2" tabindex="-1">Google OAuth2 <a class="header-anchor" href="#google-oauth2" aria-label="Permalink to &quot;Google OAuth2&quot;">​</a></h2><p>Pour les modèles de l&#39;Atelier d&#39;Outils qui interagissent avec les services Google (Calendar, Gmail), vous pouvez configurer OAuth2 :</p><ol><li>Saisissez votre <strong>Client ID</strong> depuis la Google Cloud Console</li><li>Cliquez sur <strong>Connecter</strong> pour autoriser l&#39;accès</li><li>Une fois connecté, les outils utilisant Google peuvent accéder à votre compte</li></ol><div class="warning custom-block"><p class="custom-block-title">Confidentialité</p><p>Les tokens OAuth sont stockés localement dans votre navigateur. LLMxRay n&#39;envoie jamais vos identifiants à un serveur externe.</p></div><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Commencez avec les valeurs par défaut</strong> -- La température par défaut (0.7) et la longueur de contexte fonctionnent bien pour la plupart des modèles.</li><li><strong>Réduisez la longueur de contexte</strong> si vous manquez de RAM/VRAM.</li><li>Le testeur de connexion est le moyen le plus rapide de diagnostiquer les problèmes de type &quot;aucun modèle&quot;.</li></ul>',31)])])}const h=t(s,[["render",l]]);export{m as __pageData,h as default};
